create table if not exists public.status_updates(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, kind text not null check(kind in ('text','photo','video')), content text not null default '' check(length(content)<=10000), media_path text, created_at timestamptz not null default now(), expires_at timestamptz not null default now()+interval '24 hours', check((kind='text' and media_path is null and length(trim(content))>0) or (kind in ('photo','video') and media_path is not null)));
create table if not exists public.status_views(status_id uuid references public.status_updates(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(status_id,user_id));
create table if not exists public.status_reactions(status_id uuid references public.status_updates(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,reaction text not null check(reaction in ('❤️','😊','😂','🔥')),created_at timestamptz not null default now(),primary key(status_id,user_id));
create table if not exists public.status_comments(id uuid primary key default gen_random_uuid(),status_id uuid not null references public.status_updates(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,content text not null check(length(trim(content))>0 and length(content)<=10000),created_at timestamptz not null default now());
create table if not exists public.status_activity(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references auth.users(id) on delete cascade,actor_id uuid not null references auth.users(id) on delete cascade,status_id uuid not null references public.status_updates(id) on delete cascade,kind text not null check(kind in ('reply','reaction')),content text not null,created_at timestamptz not null default now());
create index if not exists status_updates_expiry on public.status_updates(expires_at);
create index if not exists status_activity_recipient on public.status_activity(recipient_id,created_at desc);
alter table public.status_updates enable row level security;
alter table public.status_views enable row level security;
alter table public.status_reactions enable row level security;
alter table public.status_comments enable row level security;
alter table public.status_activity enable row level security;
create or replace function public.status_active(target uuid) returns boolean language sql stable security definer set search_path=public as $$select auth.uid() is not null and exists(select 1 from public.status_updates where id=target and expires_at>now())$$;
revoke all on function public.status_active(uuid) from public; grant execute on function public.status_active(uuid) to authenticated;
create or replace function public.status_stamp() returns trigger language plpgsql set search_path=public as $$begin new.created_at:=clock_timestamp(); if TG_TABLE_NAME='status_updates' then new.expires_at:=new.created_at+interval '24 hours'; if new.media_path is not null and split_part(new.media_path,'/',1)<>new.owner_id::text then raise exception 'Invalid media owner'; end if; end if; return new; end$$;
create or replace function public.status_notify() returns trigger language plpgsql security definer set search_path=public as $$declare recipient uuid; begin select owner_id into recipient from public.status_updates where id=new.status_id and expires_at>now(); if recipient is not null and recipient<>new.user_id then insert into public.status_activity(recipient_id,actor_id,status_id,kind,content) values(recipient,new.user_id,new.status_id,case when TG_TABLE_NAME='status_comments' then 'reply' else 'reaction' end,case when TG_TABLE_NAME='status_comments' then new.content else new.reaction end); end if; return new; end$$;
revoke all on function public.status_notify() from public;
drop trigger if exists status_creation on public.status_updates; create trigger status_creation before insert on public.status_updates for each row execute function public.status_stamp();
drop trigger if exists status_comment_creation on public.status_comments; create trigger status_comment_creation before insert on public.status_comments for each row execute function public.status_stamp();
drop trigger if exists status_reaction_creation on public.status_reactions; create trigger status_reaction_creation before insert on public.status_reactions for each row execute function public.status_stamp();
drop trigger if exists status_view_creation on public.status_views; create trigger status_view_creation before insert on public.status_views for each row execute function public.status_stamp();
drop trigger if exists status_reply_notify on public.status_comments; create trigger status_reply_notify after insert on public.status_comments for each row execute function public.status_notify();
drop trigger if exists status_reaction_notify on public.status_reactions; create trigger status_reaction_notify after insert on public.status_reactions for each row execute function public.status_notify();
drop policy if exists status_read on public.status_updates; create policy status_read on public.status_updates for select to authenticated using(expires_at>now());
drop policy if exists status_add on public.status_updates; create policy status_add on public.status_updates for insert to authenticated with check(owner_id=auth.uid());
drop policy if exists status_delete on public.status_updates; create policy status_delete on public.status_updates for delete to authenticated using(owner_id=auth.uid());
drop policy if exists status_views_read on public.status_views; create policy status_views_read on public.status_views for select to authenticated using(public.status_active(status_id) and (user_id=auth.uid() or exists(select 1 from public.status_updates s where s.id=status_id and s.owner_id=auth.uid())));
drop policy if exists status_views_add on public.status_views; create policy status_views_add on public.status_views for insert to authenticated with check(user_id=auth.uid() and public.status_active(status_id));
drop policy if exists status_reactions_read on public.status_reactions; create policy status_reactions_read on public.status_reactions for select to authenticated using(public.status_active(status_id));
drop policy if exists status_reactions_add on public.status_reactions; create policy status_reactions_add on public.status_reactions for insert to authenticated with check(user_id=auth.uid() and public.status_active(status_id));
drop policy if exists status_reactions_delete on public.status_reactions; create policy status_reactions_delete on public.status_reactions for delete to authenticated using(user_id=auth.uid());
drop policy if exists status_comments_read on public.status_comments; create policy status_comments_read on public.status_comments for select to authenticated using(public.status_active(status_id));
drop policy if exists status_comments_add on public.status_comments; create policy status_comments_add on public.status_comments for insert to authenticated with check(user_id=auth.uid() and public.status_active(status_id));
drop policy if exists status_comments_delete on public.status_comments; create policy status_comments_delete on public.status_comments for delete to authenticated using(user_id=auth.uid());
drop policy if exists status_activity_read on public.status_activity; create policy status_activity_read on public.status_activity for select to authenticated using(recipient_id=auth.uid() and public.status_active(status_id));
grant select,insert,delete on public.status_updates,public.status_reactions,public.status_comments to authenticated;
grant select,insert on public.status_views to authenticated; grant select on public.status_activity to authenticated;
revoke all on public.status_updates,public.status_views,public.status_reactions,public.status_comments,public.status_activity from anon;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('status-media','status-media',false,104857600,array['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime','video/3gpp']) on conflict(id) do nothing;
drop policy if exists status_media_add on storage.objects; create policy status_media_add on storage.objects for insert to authenticated with check(bucket_id='status-media' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists status_media_read on storage.objects; create policy status_media_read on storage.objects for select to authenticated using(bucket_id='status-media' and exists(select 1 from public.status_updates s where s.media_path=name and s.expires_at>now()));
drop policy if exists status_media_delete on storage.objects; create policy status_media_delete on storage.objects for delete to authenticated using(bucket_id='status-media' and (storage.foldername(name))[1]=auth.uid()::text);
